    #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, JsonSchema)]
    #[schemars(with = "String")]
    pub(super) struct ProductName(String);

    impl ProductName {
        fn parse(raw: impl AsRef<str>) -> Result<Self, SuccessorError> {
            let raw = raw.as_ref();
            let valid = !raw.is_empty()
                && raw.len() <= 63
                && raw
                    .bytes()
                    .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
                && raw.bytes().next().is_some_and(|byte| byte.is_ascii_alphanumeric())
                && raw.bytes().last().is_some_and(|byte| byte.is_ascii_alphanumeric());
            if !valid {
                return Err(SuccessorError::InvalidProductName { raw: raw.to_string() });
            }
            Ok(Self(raw.to_string()))
        }

        fn as_str(&self) -> &str {
            &self.0
        }
    }

