        #[test]
        fn manifest_metadata_and_checksum_are_bound_without_circularity() {
            let intent = intent();
            let mut entries = intent
                .slots
                .iter()
                .cloned()
                .map(|slot| ReleaseArtifactEntry {
                    digest: ArtifactDigest::from_bytes(slot.file_name().as_bytes()),
                    byte_length: slot.file_name().len() as u64,
                    source_commit: commit(),
                    provenance: slot.policy().clone(),
                    slot,
                })
                .collect::<Vec<_>>();
            let manifest = ReleaseArtifactManifest::new(&intent, entries.clone()).unwrap();
            let metadata = ReleaseDistributionMetadataV1::from_manifest(&intent, &manifest).unwrap();
            let metadata_digest = ArtifactDigest::from_bytes(metadata.canonical_json());
            entries
                .iter_mut()
                .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
                .unwrap()
                .digest = metadata_digest.clone();
            let manifest = ReleaseArtifactManifest::new(&intent, entries).unwrap();
            let roster = checksum_roster(&intent, &manifest, metadata_digest).unwrap();
            assert_eq!(roster.len(), 5);
            assert!(roster.iter().all(|entry| entry.file_name != CHECKSUM_FILE_NAME));
            assert!(roster.iter().any(|entry| entry.file_name == METADATA_FILE_NAME));
            assert!(roster.iter().all(|entry| entry.line().contains("  ")));
            let mut forged = manifest.clone();
            forged.entries[0].source_commit = CommitSha::parse(&"b".repeat(40)).unwrap();
            assert!(forged.validate_for_intent(&intent).is_err());
            let mut metadata_wire = serde_json::to_value(metadata).unwrap();
            metadata_wire["unknown"] = serde_json::Value::Bool(true);
            assert!(serde_json::from_value::<ReleaseDistributionMetadataV1>(metadata_wire).is_err());
        }
    }
}

